<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';login_required();$pdo=db();$old=isset($_GET['id'])?urldecode((string)$_GET['id']):post('old_type');$r=['room_type'=>'','room_price'=>'','room_details'=>'','room_quantity'=>0];if($old!==''){$s=$pdo->prepare('SELECT * FROM room_type WHERE room_type=?');$s->execute([$old]);$r=$s->fetch()?:$r;}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=post('type');$price=(float)($_POST['price']??0);$details=post('details');$qty=post_int('quantity');if($old!=='')$pdo->prepare('UPDATE room_type SET room_price=?,room_details=?,room_quantity=? WHERE room_type=?')->execute([$price,$details,$qty,$old]);else{$exists=$pdo->prepare('SELECT COUNT(*) FROM room_type WHERE room_type=?');$exists->execute([$type]);if($exists->fetchColumn())flash('error','Room type already exists.');else{$pdo->prepare('INSERT INTO room_type(room_type,room_price,room_details,room_quantity) VALUES(?,?,?,?)')->execute([$type,$price,$details,$qty]);flash('success','Room type added.');redirect('room_types.php');} }if($old!==''){flash('success','Room type updated.');redirect('room_types.php');}}page_header($old?'Edit Room Type':'Add Room Type','room_type');?>
<div class="page-head"><h1><?=$old?'Edit':'Add'?> Room Type</h1><a class="btn" href="room_types.php">Back</a></div><form class="card form-grid" method="post"><?=csrf_field()?><input type="hidden" name="old_type" value="<?=e($old)?>"><label>Room Type<input name="type" value="<?=e($r['room_type'])?>" <?=$old?'readonly':''?> required></label><label>Price<input type="number" min="0" step="0.01" name="price" value="<?=e($r['room_price'])?>" required></label><label>Quantity<input type="number" min="0" name="quantity" value="<?=e($r['room_quantity'])?>"></label><label class="full">Details<input name="details" value="<?=e($r['room_details'])?>"></label><div class="full"><button class="btn primary">Save Room Type</button></div></form><?php page_footer();?>
